import XCTest
@testable import StrandAnalytics

/// The Python Inertia service (`python -m activity_context.inertia.serve`) and this package meet at the
/// `motion-heads-1` response. These tests decode the golden response the Python side writes
/// (`Tools/ActivityContext/fixtures/inertia/golden_motion_heads_response.json`, regenerated by
/// `activity_context.inertia.make_golden`) and push it through the track builder, so a renamed key, a changed
/// class order, a rounding change that breaks the sums or a schema change fails here instead of silently
/// dropping the evidence. Skipped until the fixture exists.
///
/// The fixture comes from a STAND-IN encoder (no Inertia-1 checkpoint is published), so it is refused as
/// evidence unless the test-only override is set — which is exactly what these tests check.
final class MotionHeadsContractTests: XCTestCase {

    private func goldenData() throws -> Data {
        // …/Packages/StrandAnalytics/Tests/StrandAnalyticsTests/<this file> → four levels up is the repository root.
        var url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        for _ in 0..<4 { url.deleteLastPathComponent() }
        url.appendPathComponent("Tools/ActivityContext/fixtures/inertia/golden_motion_heads_response.json")
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw XCTSkip("Python golden motion-heads response not found at \(url.path)")
        }
        return try Data(contentsOf: url)
    }

    private func golden() throws -> MotionHeadsResponse {
        try MotionHeadsResponse.decode(try goldenData())
    }

    func testTheGoldenResponseThePythonServiceWritesDecodes() throws {
        let r = try golden()
        XCTAssertEqual(r.bundle.preprocessingVersion, MotionHeadsWire.preprocessingVersion)
        XCTAssertFalse(r.windows.isEmpty)
        XCTAssertTrue(MotionHeadsWire.allowedWindowS.contains(r.bundle.windowS))
        XCTAssertTrue(MotionHeadsWire.allowedHopS.contains(r.bundle.hopS))
        for (i, w) in r.windows.enumerated() {
            XCTAssertEqual(w.endTs - w.startTs, r.bundle.windowS)
            if i > 0 { XCTAssertGreaterThan(w.startTs, r.windows[i - 1].startTs) }
            for head in MotionHead.allCases {
                guard let probs = w.probabilities(head) else { continue }
                XCTAssertEqual(Set(probs.keys), Set(r.bundle.heads[head]?.prior.keys ?? [:].keys), "\(head) of window \(i)")
            }
        }
        for (head, spec) in r.bundle.heads { XCTAssertEqual(spec.classOrder, head.classOrder) }
        // Re-encoding the bundle in the wire layout decodes to the same thing.
        let again = try JSONDecoder().decode(MotionHeadsBundleInfo.self, from: JSONEncoder().encode(r.bundle))
        XCTAssertEqual(again, r.bundle)
        if r.bundle.encoderKind == .standin {
            XCTAssertTrue(r.bundle.encoderId.hasPrefix("standin:"))
            XCTAssertEqual(MotionHeadsEvidenceConfig.candidate(bundle: r.bundle).evidenceRefusal, "encoder_kind_standin")
        }
    }

    func testTheGoldenResponseDrivesTheDecoderDeterministically() throws {
        let r = try golden()
        let first = try XCTUnwrap(r.windows.first).startTs, last = try XCTUnwrap(r.windows.last).endTs
        // Synthetic 1 Hz strap streams covering the windows (and a margin), aligned to their times.
        var sim = ActivitySim(start: first - 30, seed: 13)
        let span = last - first + 60
        sim.desk(span / 3)
        sim.walk(span / 3)
        sim.still(span - 2 * (span / 3))
        var input = sim.trackInput()
        input.motionHeads = MotionHeadsTrackInput(bundle: r.bundle, windows: r.windows)

        var config = ActivityDecoderConfig()
        config.motionHeads = MotionHeadsEvidenceConfig.candidate(bundle: r.bundle)
        config.motionHeads?.allowStandInEvidenceForTesting = true
        let a = TrackKit.builtTrack(input, config: config)
        let b = TrackKit.builtTrack(input, config: config)
        let e = JSONEncoder()
        e.outputFormatting = [.sortedKeys]
        XCTAssertEqual(try e.encode(a.states), try e.encode(b.states))
        XCTAssertEqual(try e.encode(a.snapshot), try e.encode(b.snapshot))

        let stamp = try XCTUnwrap(config.motionHeads?.provenanceStamp)
        XCTAssertEqual(a.motionHeads?.stamp, stamp)
        XCTAssertEqual(a.motionHeads?.attached, r.windows.count, "every golden window lands on an observed second")
        XCTAssertGreaterThan(a.motionHeads?.evidenceSeconds ?? 0, 0)
        XCTAssertTrue(a.states.allSatisfy { $0.versions.motionHeads == stamp })
        if r.bundle.encoderKind == .standin { XCTAssertTrue(stamp.hasPrefix("standin-test:"), stamp) }
        XCTAssertTrue(stamp.contains(r.bundle.bundle12))

        // Without the override the stand-in is refused and the decode is the Inertia-free one, byte for byte.
        var refused = ActivityDecoderConfig()
        refused.motionHeads = MotionHeadsEvidenceConfig.candidate(bundle: r.bundle)
        let plain = TrackKit.builtTrack(sim.trackInput())
        let ignored = TrackKit.builtTrack(input, config: refused)
        if r.bundle.encoderKind == .standin {
            XCTAssertEqual(ignored.motionHeads?.refusal, "encoder_kind_standin")
            XCTAssertEqual(try e.encode(ignored.states), try e.encode(plain.states))
            XCTAssertEqual(try e.encode(ignored.snapshot), try e.encode(plain.snapshot))
        }
    }
}
